const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));

function ttPathRoute(){const m=location.pathname.match(/^\/([a-z0-9-]+-(?:sk|mb|ab|bc|on|qc|nb|ns|pe|nl|yt|nt|nu))(\/archive)?\/?$/);return m?"t-"+m[1]+(m[2]?"/archive":""):"";}
function ttCleanUrl(r){const m=String(r).match(/^t-([a-z0-9-]+)(\/archive)?$/);if(!m)return;const p="/"+m[1]+(m[2]||"");if(location.pathname+location.hash!==p){try{history.replaceState(null,"",p);}catch(e){}}}
function ttIsImg(u){return /\.(jpe?g|png|webp|gif)(\?|#|$)/i.test(String(u||""));}
function ttMedia(u,alt){u=String(u||"");const e=esc(u);
if(/\.pdf(\?|#|$)/i.test(u))return `<a class="filecard" href="${e}" target="_blank" rel="noopener">Open the PDF (opens in a new tab)</a>`;
if(/\.(mp3|m4a|wav|weba)(\?|#|$)/i.test(u))return `<audio controls preload="none" src="${e}"></audio>`;
if(/\.(mp4|mov|webm)(\?|#|$)/i.test(u))return `<video controls preload="metadata" playsinline src="${e}"></video>`;
return `<img src="${e}" alt="${esc(alt||"")}">`;}
function contactCard(w){
const rows=[];let host="";
const web=/^https?:\/\//i.test(w.office_website||"")?w.office_website:"";
if(web){try{host=new URL(web).hostname.replace(/^www\./,"");}catch(e){host=web;}}
if(w.office_phone)rows.push(`<dt>Phone</dt><dd><a href="tel:${esc(String(w.office_phone).replace(/[^0-9+]/g,""))}">${esc(w.office_phone)}</a></dd>`);
if(w.office_email)rows.push(`<dt>Email</dt><dd><a href="mailto:${esc(w.office_email)}">${esc(w.office_email)}</a></dd>`);
if(web)rows.push(`<dt>Website</dt><dd><a href="${esc(web)}" target="_blank" rel="noopener">${esc(host)}</a></dd>`);
if(w.office_address)rows.push(`<dt>Address</dt><dd>${esc(w.office_address)}</dd>`);
const src=/^https?:\/\//i.test(w.office_source_url||"")?w.office_source_url:"";
let tail="";
if(rows.length)tail=`<dl class="kv">${rows.join("")}</dl><p class="small muted">${esc(w.office_name||"Town office")}${src?` · <a href="${esc(src)}" target="_blank" rel="noopener">source</a>`:""} · Wrong or out of date? <a href="#corrections">Tell us</a>.</p>`;
else if(w.contact_status==="queued"||w.contact_status==="running")tail=`<p class="small muted">We're looking up the office details for ${esc(w.name)}.</p>`;
return `<aside class="contactcard" aria-label="Contact the ${esc(w.name)} office"><h2>Add to ${esc(w.name)}'s history</h2><p>Call your local town administration to add historical information and pictures to the site.</p>${tail}</aside>`;}
function ttErr(m){const e=new Error(m);e.ttUser=true;return e;}
function ttPickFile(f,ev){
const prev=document.getElementById("u-prev");const MAX=25*1024*1024;
const okType=/^(application\/pdf|audio\/(mpeg|mp4|x-m4a|wav|webm)|video\/(mp4|quicktime|webm))$/.test(f.type)||/^image\//.test(f.type);
if(!okType){prev.innerHTML='<p class="err">That file type isn\'t accepted. Use a photo, PDF, MP3/M4A/WAV audio, or MP4/MOV/WebM video.</p>';ev.target.value="";return true;}
if(f.size>MAX){prev.innerHTML=`<p class="err">That file is ${(f.size/1048576).toFixed(1)} MB. The limit is 25 MB.</p>`;ev.target.value="";return true;}
if(/^image\//.test(f.type))return false;
photoBlob=f;photoData="";prev.innerHTML=`<p class="muted small">Ready to upload: <b>${esc(f.name)}</b> (${(f.size/1048576).toFixed(1)} MB)</p>`;return true;}
async function ttLargeUpload(file){
const type=file.type||"application/octet-stream";
let r;try{r=await fetch(CFG.url+"/functions/v1/api/upload-url",{method:"POST",headers:{"Content-Type":"application/json",apikey:CFG.anon,Authorization:"Bearer "+CFG.anon},body:JSON.stringify({type,size:file.size})});}catch(e){throw new Error("Network error");}
const j=await r.json().catch(()=>({}));
if(!r.ok)throw ttErr(j.error||"Couldn't start the upload.");
await new Promise((ok,bad)=>{const x=new XMLHttpRequest();x.open("PUT",j.upload_url);x.setRequestHeader("apikey",CFG.anon);x.setRequestHeader("Authorization","Bearer "+CFG.anon);
const fd=new FormData();fd.append("cacheControl","31536000");fd.append("",file);
const p=document.getElementById("u-prog");if(p){p.hidden=false;p.max=100;p.value=0;}
x.upload.onprogress=ev=>{if(p&&ev.lengthComputable)p.value=Math.round(ev.loaded/ev.total*100);};
x.onload=()=>x.status<300?ok():bad(ttErr("The file didn't finish uploading ("+x.status+"). Please try again."));
x.onerror=()=>bad(ttErr("The connection dropped during the upload. Please try again."));x.send(fd);});
return j.public_url;}
